(r/'test/owner-monitoring.test.mjs').write_text('import test from \'node:test\';import assert from \'node:assert/strict\';import {mkdtempSync,rmSync,readFileSync} from \'node:fs\';import {tmpdir} from \'node:os\';import path from \'node:path\';import {createHmac} from \'node:crypto\';import vm from \'node:vm\';\nimport {createApplication} from \'../server/index.mjs\';import {initialState,execute,engine} from \'../server/engine.mjs\';\ntest(\'only Steven can request staff usage reports, including exclusion of a valid delegated administrator and viewer\',async()=>{\n const dir=mkdtempSync(path.join(tmpdir(),\'tharon-owner-monitor-\')),secret=\'synthetic-monitor-secret\',delegate=\'a\'.repeat(64),viewer=\'b\'.repeat(64);\n const app=await createApplication({schedule:false,env:{NODE_ENV:\'test\',APP_MODE:\'live\',PHI_APPROVED:\'true\',DATABASE_URL:\'\',SQLITE_PATH:path.join(dir,\'db\'),APP_ORIGIN:\'\',SESSION_SECRET:secret,DELEGATE_ACCESS_HASH:delegate,DELEGATE_ACCESS_EXPIRES_AT:new Date(Date.now()+3600000).toISOString(),VIEWER_ACCESS_HASH:viewer,VIEWER_ACCESS_EXPIRES_AT:new Date(Date.now()+3600000).toISOString()}});await new Promise(r=>app.server.listen(0,\'127.0.0.1\',r));const origin=\'http://127.0.0.1:\'+app.server.address().port;\n try{for(const uid of [\'u0\',\'u1\',\'u2\',\'u3\',\'u4\',\'u5\']){const csrf=(uid===\'u4\'?delegate+\'.\':uid===\'u5\'?viewer+\'.\':\'\')+\'synthetic-csrf\';await app.store.query(\'INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)\',[createHmac(\'sha256\',secret).update(uid).digest(\'hex\'),uid,Date.now()+60000,csrf]);assert.equal((await fetch(origin+\'/api/state\',{headers:{Cookie:\'tl_session=\'+uid}})).status,200,\'valid session \'+uid);const r=await fetch(origin+\'/api/admin/activity\',{headers:{Cookie:\'tl_session=\'+uid}});assert.equal(r.status,uid===\'u0\'?200:403,uid);if(uid!==\'u0\')assert.ok(!JSON.stringify(await r.json()).includes(\'lastSignInAt\'));}assert.equal((await fetch(origin+\'/api/admin/activity\')).status,401);}finally{await app.close();rmSync(dir,{recursive:true,force:true});}\n});\ntest(\'staff inactivity metrics and UI are Steven-only while creation age remains available to all users\',()=>{\n let state=execute(initialState(false),\'u0\',{op:\'createLead\',createdId:\'L_privacy_example\',args:[{first:\'Synthetic\',last:\'Monitor\',building:\'hallmark\',rep:\'u2\',payer:\'Private pay\'}]});const owner=engine(state,\'u0\'),l=owner.Lead(\'L_privacy_example\');l.created=owner.addDays(-30);l.activity=[];\n const source=readFileSync(new URL(\'../site/app.js\',import.meta.url),\'utf8\'),textFn=source.slice(source.indexOf(\'function leadAgingText(\'),source.indexOf(\'function leadCard(\'));\n for(const uid of [\'u0\',\'u1\',\'u2\',\'u3\',\'u4\',\'u5\']){const tl=engine(owner.S,uid),lead=tl.Lead(l.id),aging=tl.leadAging(lead);assert.equal(aging.openDays,30);assert.equal(aging.noUpdateDays,uid===\'u0\'?30:null);assert.equal(tl.matchesLeadAging(lead,{updateDays:3}),uid===\'u0\');const ctx={TL:tl,canMonitorStaff:()=>uid===\'u0\',fmtDate:x=>x,esc:x=>x};vm.createContext(ctx);vm.runInContext(textFn,ctx);const html=ctx.leadAgingText(lead);assert.ok(html.includes(\'Open 30 days\'));assert.equal(html.includes(\'No staff update\'),uid===\'u0\');}\n assert.match(source,/\\[\'7\',\'7\\+ days\'\\],\\[\'14\',\'14\\+ days\'\\],\\[\'30\',\'30\\+ days\'\\]/);assert.ok(!source.includes("[\'13\',\'13+ days\']"));assert.ok(!source.includes(\'<small>Overdue next steps</small>\'));\n});\n')
